import{_ as l,l as i,o as e,c as n,v as r,p as s,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"前导零计数与规格化","description":"","frontmatter":{"title":"前导零计数与规格化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lzc-normalize.md","filePath":"cs/lzc-normalize.md","lastUpdated":1789023840000}'),E={name:"cs/lzc-normalize.md"};function h(m,a,_,A,u,f){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="前导零计数与规格化" tabindex="-1">前导零计数与规格化 <a class="header-anchor" href="#前导零计数与规格化" aria-label="Permalink to &quot;前导零计数与规格化&quot;">​</a></h1><div class="epigraph"><p>有效减法之后，尾数前面可能空出许多零；先数有多少个，再一次左移，指数跟着减，规格化才不是逐位试探。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Ercegovac and Lang, Digital Arithmetic；IEEE Std 754-2008 整理</footer></div><p><a href="/cs/fp-exceptions">上一课</a>在舍入之后采样下溢与不精确。<a href="/cs/fp-adder">浮点加法器</a>已经说：对消后要左规。缺口是硬件：<strong>前导零计数（LZC）</strong> 把移位量一次算出来，而不是循环左移直到最高位为 1。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有效减的尾数和可能是 \\(0.0001\\ldots\\) 形式。逐位规格化要 \\(\\Theta(n)\\) 拍，与组合加法器的设计目标冲突。LZC：组合优先级编码器，输出前导零个数 \\(k\\)，尾数左移 \\(k\\)，指数减 \\(k\\)。若 \\(k\\) 大于指数能减的量，结果变成非规格化或零，并影响<a href="/cs/fp-exceptions">下溢标志</a>。缺口不是 754 的隐藏位定义，而是这条优先级编码路径的延迟——它常与对阶移位器对称，是浮点加的关键路径之一。</p><h3 id="lzc-不是「整数-clz-指令的软件仿真」" tabindex="-1">LZC 不是「整数 clz 指令的软件仿真」 <a class="header-anchor" href="#lzc-不是「整数-clz-指令的软件仿真」" aria-label="Permalink to &quot;LZC 不是「整数 clz 指令的软件仿真」&quot;">​</a></h3><p>ISA 上的 <code>clz</code>（后课位操作扩展）与 FPU 内部 LZC 可以共用同一类电路，但浮点规格化还要改指数、处理全零（和为 0 则指数走零编码，不左移 24 位）。把规格化理解成编译器插入 <code>clz</code>，软浮点可以，硬 FPU 是数据通路上的固定级。</p><p><span class="marginnote">Harris 用优先级编码器教 LZC。Ercegovac/Lang 把规格化写成算术算法步骤。754 区分规格化与非规格化编码，电路必须两者都能递送。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>尾数（含保护位）进前导零/前导一检测。全零：结果 ±0，清尾数。否则桶形左移 \\(k\\)，指数减 \\(k\\)；若指数将穿过 0，改为非规格化右移规则（指数钉在 min，隐藏位为 0）。右规（乘/加进位）是固定移 1 或 2 位，通常不用完整 LZC。</p>',10)),(e(),s(p,null,{default:t(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUM%5B%22%E5%B0%BE%E6%95%B0%E5%92%8C%22%5D%20--%3E%20LZC%5B%22%E5%89%8D%E5%AF%BC%E9%9B%B6%E8%AE%A1%E6%95%B0%22%5D%0A%20%20LZC%20--%3E%20SHL%5B%22%E6%A1%B6%E5%BD%A2%E5%B7%A6%E7%A7%BB%22%5D%0A%20%20LZC%20--%3E%20EXP%5B%22%E6%8C%87%E6%95%B0%E5%87%8F%20k%22%5D%0A%20%20SHL%20--%3E%20RND%5B%22%E5%86%8D%E8%88%8D%E5%85%A5%22%5D%0A%20%20RND%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AE%9A%E7%82%B9%20DSP%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>FMA 有效减同样走 LZC；乘积在 \\([1,4)\\) 时最多右规 1 位，LZC 不是乘路径的主角。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课定点 DSP 常不做规格化，小数点钉死，溢出走饱和——对照本课：浮点用指数把动态范围换成分档精度。整数 <code>clz</code> 在 ISA 对照课才会作为用户指令出现；本课只为 FPU 内部服务。</p><p>延迟：LZC + 桶形移位 ≈ 对阶移位器，近路径加法器因此难做得很浅。这是浮点加比整数加慢的结构原因之一。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Lod（leading-one detector）的每级电路画成晶体管，不讨论预测规格化（提前猜 \\(k\\)）。不把 subnormal 的刷新延迟（微结构上的微码协助）写成 754 语义。</p><p>后课默认：规格化左移量由 LZC 一次给出；指数不够减则走非规格化或零。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对消后的左规依赖前导零计数，不是逐位循环。</li><li>\\(k\\) 同时驱动移位与指数；下溢在此分叉。</li><li>定点通路没有这一级，下一课对照。</li><li>出处：Harris and Harris；Ercegovac and Lang；IEEE 754-2008。</li></ul>',9))])}const L=l(E,[["render",h]]);export{C as __pageData,L as default};
